// 声明变量
VAR
  bStart : BOOL := FALSE;
  nSpeed : INT := 0;
  rTemp  : REAL := 25.5;
  sMsg   : STRING[20];
END_VAR

// 绝对寻址
A I 0.0       // 读取输入点 0.0
= Q 0.0       // 输出到 0.0
L MW 10       // 加载中间字 MW10
T DB1.DBW 2   // 传送到 DB1 的字 2

// 符号寻址（推荐）
"Motor"."Start" := TRUE;

// LAD（梯形图）
// |   I0.0     Q0.0   |
// |---| |-------( )---|
//     |               |
// |   I0.1           |
// |---|/|------------|

// SCL 实现 LAD 逻辑
IF "Start" AND NOT "Stop" THEN
  "Motor" := TRUE;
END_IF;

// FBD 以图形方式连接功能块
// 类似 SCL 的布尔运算
"Motor" := "Start" AND NOT "Stop";
"Alarm" := ("Temp" > 80) OR ("Pressure" > 100);

// SCL 示例：FOR 循环求数组平均值
#avg := 0;
FOR #i := 1 TO 10 DO
  #avg := #avg + "DataDB".values[#i];
END_FOR;
#avg := #avg / 10;

// CASE 分支
CASE #state OF
  0: "Idle"();
  1: "Running"();
  2: "Error"();
END_CASE;

// OB100（启动组织块）
// 仅在 PLC 启动时执行一次，用于初始化
"DataDB".counter := 0;
"DataDB".init := TRUE;

// OB1（主循环）
// 周期性执行，是主程序入口
CALL "FC_Control"

// FC 声明
FUNCTION "CalcAvg" : REAL
VAR_INPUT
  a, b, c : REAL;
END_VAR
// FC 调用
#result := "CalcAvg"(a:=1.0, b:=2.0, c:=3.0);

// 全局 DB 声明（DB1）
DATA_BLOCK "RecipeDB"
STRUCT
  setTemp : REAL := 25.0;
  setSpeed : INT := 1500;
  parts : ARRAY[1..100] OF INT;
END_STRUCT
BEGIN
END_DATA_BLOCK

// 访问
"RecipeDB".setTemp := 30.0;

// C# 通过 s7netplus 连接西门子 S7 PLC（推荐方案）
// 来源：github.com/S7NetPlus/s7netplus  NuGet: Install-Package S7netplus
using S7.Net;
using S7.Net.Types;

// 地址格式示例：
//   DB10.DBD0  -> REAL at DB10, offset 0
//   DB10.DBW4  -> INT/WORD at DB10, offset 4
//   DB10.DBX0.0-> BOOL at DB10, byte 0, bit 0
//   M0.0 / MW10 / I0.0 / Q0.0

var plc = new Plc(CpuType.S71500, '192.168.1.10', 0, 1);
plc.Open();

// 读单个变量（按地址字符串）
object temp = plc.Read('DB10.DBD0');   // 返回 float
object speed = plc.Read('DB10.DBW4');  // 返回 Int16
bool motor = (bool)plc.Read('DB10.DBX0.0');

// 写变量
plc.Write('DB10.DBD0', 75.5f);
plc.Write('DB10.DBX0.0', true);

// 批量读（推荐，减少往返）
var db10 = plc.ReadClass<DB10Class>(DBType.DB, 10);
plc.Close();

// C# 通过 Sharp7 连接 S7-1200/1500（备选方案）
// 来源：github.com/fbarresi/Sharp7  NuGet: Install-Package Sharp7
// 注意：S7-1500 需关闭 DB 'optimized block access' 并启用 GET/PUT
using Sharp7;

var client = new S7Client();
// Connect(ip, rack, slot, port=102)
int result = client.ConnectTo('192.168.1.10', 0, 1);
if (result == 0)
{
    // 读 DB1.DBX0.0（BOOL）
    byte[] buffer = new byte[1];
    client.DBRead(1, 0, 1, buffer);
    bool bit = (buffer[0] & 0x01) != 0;

    // 读 DB1.DBD4（REAL, 4 字节）
    byte[] floatBuf = new byte[4];
    client.DBRead(1, 4, 4, floatBuf);
    float temp = BitConverter.ToSingle(floatBuf, 0);
    // 注意：S7 使用大端序，需根据平台翻转
    client.Disconnect();
}

// ===== 案例 1：电机起保停（最基础） =====
// 硬件：I0.0=启动按钮(NO), I0.1=停止按钮(NC), Q0.0=电机接触器
// 逻辑：按下启动→电机运行；松开启动→自锁保持；按下停止→电机停止
// SCL 实现：
IF "Start" THEN
    "Motor" := TRUE;           // 启动
END_IF;
IF "Stop" THEN
    "Motor" := FALSE;          // 停止
END_IF;
// 注意：停止优先级高于启动

// ===== 案例 2：正反转控制（互锁） =====
// 硬件：I0.0=正转按钮, I0.1=反转按钮, I0.2=停止
//       Q0.0=正转接触器, Q0.1=反转接触器
// 关键：两个方向不能同时接通（短路）
IF "Forward_Btn" AND NOT "Reverse_Motor" THEN
    "Forward_Motor" := TRUE;
END_IF;
IF "Reverse_Btn" AND NOT "Forward_Motor" THEN
    "Reverse_Motor" := TRUE;
END_IF;
IF "Stop_Btn" THEN
    "Forward_Motor" := FALSE;
    "Reverse_Motor" := FALSE;
END_IF;

// ===== 案例 3：星三角启动 =====
// 启动顺序：主接触器 + 星形接触器 → 延时 → 断开星形 → 接通三角形
// 时间：星形运行 5-10 秒后切换到三角形
// 注意：星形和三角形接触器必须互锁！
CASE #state OF
  0:  // 待机
    IF "Start_Btn" THEN #state := 1; END_IF;
  1:  // 星形启动
    "Main_Contactor" := TRUE;
    "Star_Contactor" := TRUE;
    "Star_Timer".IN := TRUE;
    "Star_Timer".PT := T#6S;
    IF "Star_Timer".Q THEN #state := 2; END_IF;
  2:  // 切换（断开星形）
    "Star_Contactor" := FALSE;
    "Transition_Timer".IN := TRUE;
    "Transition_Timer".PT := T#50MS;  // 50ms 过渡
    IF "Transition_Timer".Q THEN #state := 3; END_IF;
  3:  // 三角形运行
    "Delta_Contactor" := TRUE;
    IF "Stop_Btn" THEN #state := 0; END_IF;
END_CASE;
IF "Stop_Btn" OR "Overload" THEN
    #state := 0;
    "Main_Contactor" := FALSE;
    "Star_Contactor" := FALSE;
    "Delta_Contactor" := FALSE;
END_IF;

// ===== 案例 4：传送带顺序控制 =====
// 3 条传送带：皮带3→皮带2→皮带1（物料从 1→2→3）
// 启动：先开皮带3，延时 2s 开皮带2，再延时 2s 开皮带1
// 停止：先停皮带1，延时 5s 停皮带2，再延时 5s 停皮带3
// 目的：防止物料堆积
CASE #conveyor_state OF
  0:  // 待机
    IF "Start_Btn" THEN #conveyor_state := 10; END_IF;
  10: "Conveyor3" := TRUE;  // 先开下游
    "T_ON_2".IN := TRUE; "T_ON_2".PT := T#2S;
    IF "T_ON_2".Q THEN #conveyor_state := 20; END_IF;
  20: "Conveyor2" := TRUE;
    "T_ON_1".IN := TRUE; "T_ON_1".PT := T#2S;
    IF "T_ON_1".Q THEN #conveyor_state := 30; END_IF;
  30: "Conveyor1" := TRUE;  // 正常运行
    IF "Stop_Btn" THEN #conveyor_state := 40; END_IF;
  40: "Conveyor1" := FALSE; // 先停上游
    "T_OFF_1".IN := TRUE; "T_OFF_1".PT := T#5S;
    IF "T_OFF_1".Q THEN #conveyor_state := 50; END_IF;
  50: "Conveyor2" := FALSE;
    "T_OFF_2".IN := TRUE; "T_OFF_2".PT := T#5S;
    IF "T_OFF_2".Q THEN #conveyor_state := 60; END_IF;
  60: "Conveyor3" := FALSE; #conveyor_state := 0;
END_CASE;

// C# TIA Portal Openness 示例：自动生成项目
// 引用：Siemens.Engineering.dll, Siemens.Engineering.HW.dll
// 来源：siemens.com TIA Portal Openness 开发手册
using Siemens.Engineering;
using Siemens.Engineering.HW;
using Siemens.Engineering.SW;

// 1. 创建或打开项目
var tiaPortal = new TiaPortal(
    TiaPortalMode.WithUserInterface);  // 或 WithoutUserInterface
var project = tiaPortal.Projects.Create(
    new FileInfo(@"D:\Projects\MyProject.ap17"));

// 2. 添加 S7-1200 PLC 设备
var device = project.Devices.CreateWithItem(
    "OrderNumber:6ES7 214-1AG40-0XB0",  // CPU 1214C
    "S7-1200_Station_1", "MyPLC");

// 3. 添加 HMI 设备
var hmi = project.Devices.CreateWithItem(
    "OrderNumber:6AV2 124-0GC01-0AX0",  // TP700 Comfort
    "HMI_Station_1", "MyHMI");

// 4. 创建 PLC 程序块
var plcSoftware = device.DeviceItems[1].GetService<SoftwareContainer>();
var fb = plcSoftware.Software.CreateBlock(
    plcSoftware.Software.BlockGroup,
    "FB_Motor", "MotorControl");

// 5. 保存并关闭
project.Save();
tiaPortal.Dispose();
